-- RosterOps Supabase PostgreSQL foundation
create extension if not exists pgcrypto; create extension if not exists vector;
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,kind text not null default 'agency',created_at timestamptz not null default now());
create table public.users(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid not null references organizations(id) on delete cascade,role text not null check(role in('owner','admin','manager','coordinator','finance','viewer')),full_name text,created_at timestamptz not null default now());
create table public.creators(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,handle text,email text,goals jsonb not null default '{}',preferences jsonb not null default '{}',audience_stats jsonb not null default '{}',active boolean not null default true);
create table public.brand_accounts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,domain text,industry text,enrichment jsonb not null default '{}',created_at timestamptz not null default now());
create table public.brand_contacts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,brand_account_id uuid references brand_accounts(id) on delete cascade,name text,email text,role text,verified boolean not null default false,relationship jsonb not null default '{}',warmth numeric,provenance jsonb not null default '{}');
create table public.rate_cards(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,creator_id uuid not null references creators(id) on delete cascade,name text not null,currency char(3) not null default 'USD',terms jsonb not null default '{}',effective_from date not null,effective_to date);
create table public.deals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,creator_id uuid references creators(id),brand_account_id uuid references brand_accounts(id),owner_id uuid references users(id),source text,external_id text,subject text,status text not null default 'new',brief jsonb not null default '{}',created_at timestamptz not null default now(),unique(organization_id,source,external_id));
create table public.deal_terms(id uuid primary key default gen_random_uuid(),deal_id uuid unique not null references deals(id) on delete cascade,fee numeric,currency char(3),deliverables jsonb not null default '[]',usage jsonb not null default '{}',whitelisting jsonb not null default '{}',exclusivity jsonb not null default '{}',dates jsonb not null default '{}',payment text,cancellation text,evidence jsonb not null default '{}',unknown_fields text[] not null default '{}');
create table public.campaigns(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,deal_id uuid unique not null references deals(id) on delete cascade,name text not null,status text not null default 'setup',brief jsonb not null default '{}',created_at timestamptz not null default now());
create table public.deliverables(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,campaign_id uuid not null references campaigns(id) on delete cascade,title text not null,due_at timestamptz,approval_status text not null default 'pending',owner_id uuid references users(id),metadata jsonb not null default '{}');
create table public.invoices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,campaign_id uuid references campaigns(id),creator_id uuid references creators(id),amount numeric,currency char(3),due_at date,paid_at date,status text not null default 'planned',commission_split jsonb not null default '{}');
create table public.agent_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,agent_type text not null,run_id text not null,action text not null,input jsonb not null default '{}',output jsonb not null default '{}',status text not null,requires_approval boolean not null default false,created_at timestamptz not null default now());
create table public.memory_embeddings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,memory_type text not null,entity_id uuid,content text not null,embedding vector(1536),provenance jsonb not null default '{}',expires_at timestamptz,created_at timestamptz not null default now());
create index memory_vector_idx on memory_embeddings using hnsw(embedding vector_cosine_ops); create index deals_queue on deals(organization_id,status,created_at desc);
create or replace function public.member(o uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from users where id=auth.uid() and organization_id=o)$$;
do $$declare t text; begin foreach t in array array['organizations','users','creators','brand_accounts','brand_contacts','rate_cards','deals','deal_terms','campaigns','deliverables','invoices','agent_logs','memory_embeddings'] loop execute format('alter table public.%I enable row level security',t); end loop; end$$;
create policy org_access on organizations for select using(member(id)); create policy user_access on users for all using(member(organization_id)) with check(member(organization_id));
create policy creators_access on creators for all using(member(organization_id)) with check(member(organization_id)); create policy brands_access on brand_accounts for all using(member(organization_id)) with check(member(organization_id)); create policy contacts_access on brand_contacts for all using(member(organization_id)) with check(member(organization_id)); create policy rates_access on rate_cards for all using(member(organization_id)) with check(member(organization_id)); create policy deals_access on deals for all using(member(organization_id)) with check(member(organization_id)); create policy campaigns_access on campaigns for all using(member(organization_id)) with check(member(organization_id)); create policy deliverables_access on deliverables for all using(member(organization_id)) with check(member(organization_id)); create policy invoices_access on invoices for all using(member(organization_id)) with check(member(organization_id)); create policy logs_access on agent_logs for all using(member(organization_id)) with check(member(organization_id)); create policy memory_access on memory_embeddings for all using(member(organization_id)) with check(member(organization_id));
create policy terms_access on deal_terms for all using(exists(select 1 from deals d where d.id=deal_id and member(d.organization_id))) with check(exists(select 1 from deals d where d.id=deal_id and member(d.organization_id)));